    #[test]
    fn hoist_pair_folds_to_direct_numeric_assign() {
        // t86 `_i_sqrt_n`/`_i_sqrt_nv`: the float-bound temp pair must
        // fold to one numeric assign — no string home, no strdup, no
        // snprintf temp, no atoll of the temp (the `$1` read keeps its
        // own atoll — only the temp's round-trip must vanish).
        use crate::ir::StrStyle;
        fn assign(var: &str, expr: IrExpr) -> IrStmt {
            IrStmt::Assign {
                targets: vec![crate::ir::AssignTarget {
                    var: var.to_string(),
                    sigil: None,
                    indices: vec![],
                }],
                expr,
                asm: None,
            }
        }
        let pair = vec![
            assign(
                "s",
                IrExpr::Call {
                    func: "arith".to_string(),
                    args: vec![IrExpr::Str(
                        "(int(sqrt($1)) + 1)".to_string(),
                        StrStyle::DoubleQuoted,
                    )],
                },
            ),
            assign(
                "n",
                IrExpr::Arith(Box::new(ArithAst::Bin {
                    op: "+".to_string(),
                    lhs: Box::new(ArithAst::Var("s".to_string())),
                    rhs: Box::new(ArithAst::Num(0)),
                })),
            ),
            assign("i", IrExpr::Arith(Box::new(ArithAst::Num(1)))),
            IrStmt::While {
                cond: IrExpr::Arith(Box::new(ArithAst::Bin {
                    op: "<".to_string(),
                    lhs: Box::new(ArithAst::Var("i".to_string())),
                    rhs: Box::new(ArithAst::Var("n".to_string())),
                })),
                body: vec![],
            },
        ];
        let prog = IrProgram {
            imports: vec![],
            requires: vec![],
            stmts: pair,
            subs: vec![],
            var_types: vec![],
            stmt_lines: vec![],
            var_lengths: vec![],
            var_const: vec![],
            var_lifetimes: vec![],
            var_nospace: vec![],
            var_storage: vec![],
            var_bash_env: vec![],
        };
        let out = shir_to_c(&prog);
        assert!(out.contains("long long n"), "n not homed numeric:\n{out}");
        assert!(
            out.contains("n = (long long)("),
            "bound not assigned directly:\n{out}"
        );
        assert!(
            !out.contains("char* s = NULL"),
            "string home survives:\n{out}"
        );
        assert!(!out.contains("= strdup"), "strdup survives:\n{out}");
        assert!(!out.contains("_s0"), "snprintf temp survives:\n{out}");
        assert!(!out.contains("atoll((s"), "atoll-of-temp survives:\n{out}");
        assert!(!out.contains("free(s)"), "dead free survives:\n{out}");
    }

    #[test]
    fn hoist_pair_refuses_extra_string_read() {
        // an additional `$s` read anywhere keeps the pair untouched
        // (and keeps `s` in the verdicts)
        use crate::ir::StrStyle;
        fn assign(var: &str, expr: IrExpr) -> IrStmt {
            IrStmt::Assign {
                targets: vec![crate::ir::AssignTarget {
                    var: var.to_string(),
                    sigil: None,
                    indices: vec![],
                }],
                expr,
                asm: None,
            }
        }
        let mut prog = IrProgram {
            imports: vec![],
            requires: vec![],
            stmts: vec![
                assign(
                    "s",
                    IrExpr::Call {
                        func: "arith".to_string(),
                        args: vec![IrExpr::Str(
                            "(int(sqrt($1)) + 1)".to_string(),
                            StrStyle::DoubleQuoted,
                        )],
                    },
                ),
                assign(
                    "n",
                    IrExpr::Arith(Box::new(ArithAst::Bin {
                        op: "+".to_string(),
                        lhs: Box::new(ArithAst::Var("s".to_string())),
                        rhs: Box::new(ArithAst::Num(0)),
                    })),
                ),
                IrStmt::Expr(IrExpr::Call {
                    func: "exec".to_string(),
                    args: vec![
                        IrExpr::Str("echo".to_string(), StrStyle::DoubleQuoted),
                        IrExpr::Array(vec![IrExpr::Str(
                            "$s".to_string(),
                            StrStyle::DoubleQuoted,
                        )]),
                    ],
                }),
            ],
            subs: vec![],
            var_types: vec![
                ("s".to_string(), IrType::Str),
                ("n".to_string(), IrType::Int),
            ],
            stmt_lines: vec![],
            var_lengths: vec![],
            var_const: vec![],
            var_lifetimes: vec![],
            var_nospace: vec![],
            var_storage: vec![],
            var_bash_env: vec![],
        };
        fold_hoist_pairs(&mut prog);
        assert_eq!(prog.stmts.len(), 3, "pair folded despite extra read");
        assert!(
            prog.var_types.iter().any(|(v, _)| v == "s"),
            "s dropped despite extra read"
        );
    }

    #[test]
    fn dollar_refs_rejects_name_prefix() {
        // `_i_sqrt_n` is a strict prefix of `_i_sqrt_nv`: only full
        // identifier matches count (a prefix hit would refuse every
        // real hoist pair, since `n`'s own name contains `s`)
        assert_eq!(dollar_refs("$_i_sqrt_nv", "_i_sqrt_n"), 0);
        assert_eq!(dollar_refs("$_i_sqrt_n", "_i_sqrt_n"), 1);
        assert_eq!(dollar_refs("${_i_sqrt_n}", "_i_sqrt_n"), 1);
        assert_eq!(dollar_refs("${_i_sqrt_n:-1}", "_i_sqrt_n"), 1);
        assert_eq!(dollar_refs("$_i_sqrt_nv + ${_i_sqrt_n}", "_i_sqrt_n"), 1);
        assert_eq!(dollar_refs("$@", "_i_sqrt_n"), 0);
        assert_eq!(dollar_refs("$@", "1"), 1);
        assert_eq!(str_mentions("s", "s"), 1);
        assert_eq!(str_mentions("s=1", "s"), 1);
        assert_eq!(str_mentions("echo", "s"), 0);
    }

    /// Build the vec-test program: `xs = [1, 2]` then `body` (appends),
    /// consumed by `sortedIntJoin` under `echo` (the int_arrays admission
    /// shape: all-int elements, numeric-only consumption).
    fn vec_test_prog(body: Vec<IrStmt>) -> IrProgram {
        use crate::ir::StrStyle;
        let word = |s: &str| IrExpr::Str(s.to_string(), StrStyle::DoubleQuoted);
        let mut stmts = vec![IrStmt::Assign {
            targets: vec![crate::ir::AssignTarget {
                var: "xs".to_string(),
                sigil: None,
                indices: vec![],
            }],
            expr: IrExpr::Call {
                func: "setArray".to_string(),
                args: vec![
                    word("xs"),
                    IrExpr::Array(vec![IrExpr::Int(1), IrExpr::Int(2)]),
                ],
            },
            asm: None,
        }];
        stmts.extend(body);
        stmts.push(IrStmt::Expr(IrExpr::Call {
            func: "exec".to_string(),
            args: vec![
                word("echo"),
                IrExpr::Array(vec![IrExpr::Call {
                    func: "sortedIntJoin".to_string(),
                    args: vec![word("xs")],
                }]),
            ],
        }));
        IrProgram {
            imports: vec![],
            requires: vec![],
            stmts,
            subs: vec![],
            var_types: vec![],
            stmt_lines: vec![],
            var_lengths: vec![],
            var_const: vec![],
            var_lifetimes: vec![],
            var_nospace: vec![],
            var_storage: vec![],
            var_bash_env: vec![],
        }
    }

    fn vec_append_xs() -> IrStmt {
        use crate::ir::StrStyle;
        IrStmt::Assign {
            targets: vec![crate::ir::AssignTarget {
                var: "xs".to_string(),
                sigil: None,
                indices: vec![],
            }],
            expr: IrExpr::Call {
                func: "setArrayAppend".to_string(),
                args: vec![
                    IrExpr::Str("xs".to_string(), StrStyle::DoubleQuoted),
                    IrExpr::Array(vec![IrExpr::Int(3)]),
                ],
            },
            asm: None,
        }
    }

    #[test]
    fn vec_array_grows_past_cap() {
        // unbounded append loop over an int-consumed array: pointer +
        // len + cap decl, grow helper + call, heap free — and no fixed
        // decl, no capacity exit for this array.
        let body = vec![IrStmt::While {
            // unranged counter bounds: trip unprovable → unbounded
            cond: IrExpr::Arith(Box::new(ArithAst::Bin {
                op: "<".to_string(),
                lhs: Box::new(ArithAst::Var("u".to_string())),
                rhs: Box::new(ArithAst::Var("v".to_string())),
            })),
            body: vec![vec_append_xs()],
        }];
        let out = shir_to_c(&vec_test_prog(body));
        // elements 1..3 narrow to u8: the vec is width-narrowed too
        assert!(out.contains("uint8_t *xs = NULL"), "vec decl missing:\n{out}");
        assert!(out.contains("xs_len = 0, xs_cap = 0"), "len/cap missing:\n{out}");
        assert!(
            out.contains("static void _sh_grow_u8(uint8_t **p, size_t *cap)"),
            "grow helper missing:\n{out}"
        );
        assert!(
            out.contains("_sh_grow_u8(&xs, &xs_cap)"),
            "grow call missing:\n{out}"
        );
        assert!(out.contains("free(xs);"), "heap free missing:\n{out}");
        assert!(!out.contains("xs[1024]"), "fixed decl survives:\n{out}");
        assert!(
            !out.contains("capacity exceeded: xs"),
            "capacity exit survives:\n{out}"
        );
    }

    #[test]
    fn vec_array_bounded_stays_fixed() {
        // straight-line appends (bound 4 ≤ cap): fixed storage (exact
        // proven size, not the blanket 1024), no vec machinery at all.
        let out = shir_to_c(&vec_test_prog(vec![vec_append_xs(), vec_append_xs()]));
        assert!(out.contains("xs["), "fixed decl missing:\n{out}");
        assert!(!out.contains("*xs = NULL"), "vec decl leaked:\n{out}");
        assert!(!out.contains("_sh_grow_"), "grow helper leaked:\n{out}");
        assert!(!out.contains("free(xs);"), "vec free leaked:\n{out}");
    }

    #[test]
    fn vec_array_escaped_stays_fixed() {
        // passed to an unknown callee: escape keeps fixed storage
        // (unknown code may do anything), exactly sized.
        use crate::ir::StrStyle;
        let prog = vec_test_prog(vec![IrStmt::Expr(IrExpr::Call {
            func: "exec".to_string(),
            args: vec![
                IrExpr::Str("mystery".to_string(), StrStyle::DoubleQuoted),
                IrExpr::Array(vec![IrExpr::Var("xs".to_string(), None)]),
            ],
        })]);
        let out = shir_to_c(&prog);
        assert!(out.contains("xs["), "fixed decl missing:\n{out}");
        assert!(!out.contains("*xs = NULL"), "vec decl leaked:\n{out}");
    }

    /// Big-int-literal elements (force I64 width so decl shapes are
    /// predictable) for the locality tests below.
