    #[test]
    fn vec_array_single_scope_is_fn_local() {
        // every use inside one function, none risky: pointer + len +
        // cap declare as plain (non-static) fn-top locals with a heap
        // free — no file-scope global for this array.
        let body = vec![
            set_array_xs(big_ints()),
            unbounded_while(vec![append_xs_big()]),
            echo_sorted_xs(),
        ];
        let out = shir_to_c(&fn_prog("f", body));
        assert!(
            out.contains("\n    long long *xs = NULL;"),
            "fn-local decl missing:\n{out}"
        );
        assert!(
            !out.contains("static long long *xs"),
            "file-scope decl survives:\n{out}"
        );
        assert!(out.contains("free(xs);"), "local free missing:\n{out}");
    }

    #[test]
    fn vec_array_capture_use_stays_global() {
        // a use inside a capture (file-scope helper territory) forces
        // global storage: static decl, no fn-local shadow.
        let body = vec![
            set_array_xs(big_ints()),
            unbounded_while(vec![append_xs_big()]),
            IrStmt::Assign {
                targets: vec![crate::ir::AssignTarget {
                    var: "out".to_string(),
                    sigil: None,
                    indices: vec![],
                }],
                expr: IrExpr::Capture {
                    expr: Box::new(IrExpr::Call {
                        func: "getVar".to_string(),
                        args: vec![{
                            use crate::ir::StrStyle;
                            IrExpr::Str("xs".to_string(), StrStyle::DoubleQuoted)
                        }],
                    }),
                    native: false,
                },
                asm: None,
            },
            echo_sorted_xs(),
        ];
        let out = shir_to_c(&fn_prog("f", body));
        assert!(
            out.contains("static long long *xs"),
            "global decl missing:\n{out}"
        );
        assert!(
            !out.contains("\n    long long *xs = NULL;"),
            "fn-local shadow leaked:\n{out}"
        );
    }

    #[test]
    fn vec_array_main_scope_stays_global() {
        // top-level-only uses: file-scope static is correct (main runs
        // once) and stays.
        let prog = vec_test_prog(vec![unbounded_while(vec![vec_append_xs()])]);
        let out = shir_to_c(&prog);
        // small ints narrow; either way the decl is file-scope static
        assert!(
            out.contains("static ") && out.contains("*xs = NULL;"),
            "global decl missing:\n{out}"
        );
        assert!(
            !out.contains("\n    long long *xs = NULL;")
                && !out.contains("\n    uint8_t *xs = NULL;"),
            "fn-local shadow leaked:\n{out}"
        );
    }

    #[test]
    fn not_binop_condition_keeps_sh_rc() {
        // `while not (i >= 3)` — the Not BinOp renders `!(_sh_rc = X ?
        // 1 : 0)`. strip_dead_rc must NOT strip the `_sh_rc =` from
        // inside the `!()` (that would leave a broken `!()`), and must
        // keep the `_sh_rc` declaration.
        use crate::ir::{ArithAst, BinOpKind, StrStyle};
        let cond = IrExpr::BinOp {
            lhs: Box::new(IrExpr::Arith(Box::new(ArithAst::Bin {
                op: ">=".to_string(),
                lhs: Box::new(ArithAst::Var("i".to_string())),
                rhs: Box::new(ArithAst::Num(3)),
            }))),
            op: BinOpKind::Not,
            rhs: Box::new(IrExpr::Arith(Box::new(ArithAst::Bin {
                op: ">=".to_string(),
                lhs: Box::new(ArithAst::Var("i".to_string())),
                rhs: Box::new(ArithAst::Num(3)),
            }))),
        };
        let prog = IrProgram {
            imports: vec![],
            requires: vec![],
            stmts: vec![IrStmt::While {
                cond,
                body: vec![IrStmt::Expr(IrExpr::Call {
                    func: "exec".to_string(),
                    args: vec![
                        IrExpr::Str("echo".to_string(), StrStyle::DoubleQuoted),
                        IrExpr::Array(vec![IrExpr::Str("u".to_string(), StrStyle::DoubleQuoted)]),
                    ],
                })],
            }],
            subs: vec![],
            var_types: vec![],
            stmt_lines: vec![],
            var_lengths: vec![],
            var_const: vec![],
            var_lifetimes: vec![],
            var_nospace: vec![],
            var_storage: vec![],
            var_bash_env: vec![],
        };
        let out = shir_to_c(&prog);
        assert!(
            out.contains("!(_sh_rc ="),
            "Not BinOp lost its _sh_rc write:\n{out}"
        );
        assert!(
            !out.contains("(!())"),
            "Not BinOp stripped to broken !():\n{out}"
        );
        assert!(
            out.contains("static int _sh_rc;"),
            "_sh_rc declaration stripped (item 44 renders the zero-init as bare static):\n{out}"
        );
    }

    #[test]
    fn native_num_fn_detected() {
        // A lifted function whose params are all Int-typed (not bigint)
        // and whose call sites pass small values is eligible for a native
        // `long long _pN` signature.
        use crate::ir::{ArithAst, IrType, StrStyle};
        let cast = |arg: ArithAst| ArithAst::Cast {
            ty: IrType::Int64,
            arg: Box::new(arg),
        };
        let assign = |var: &str, pos: &str| IrStmt::Assign {
            targets: vec![crate::ir::AssignTarget {
                var: var.to_string(),
                sigil: None,
                indices: vec![],
            }],
            expr: IrExpr::Arith(Box::new(cast(ArithAst::Var(pos.to_string())))),
            asm: None,
        };
        let sum = IrExpr::Arith(Box::new(ArithAst::Bin {
            op: "+".to_string(),
            lhs: Box::new(ArithAst::Var("a".to_string())),
            rhs: Box::new(ArithAst::Var("b".to_string())),
        }));
        let prog = IrProgram {
            imports: vec![],
            requires: vec![],
            stmts: vec![
                IrStmt::Function {
                    name: "add".to_string(),
                    params: vec![],
                    named_blocks: vec![],
                    body: vec![
                        assign("a", "1"),
                        assign("b", "2"),
                        IrStmt::Expr(IrExpr::Call {
                            func: "exec".to_string(),
                            args: vec![
                                IrExpr::Str("echo".to_string(), StrStyle::DoubleQuoted),
                                IrExpr::Array(vec![sum]),
                            ],
                        }),
                    ],
                },
                // a value-position call (echo <add(3,4)>) uses the
                // plain-call path with numeric args
                IrStmt::Expr(IrExpr::Call {
                    func: "exec".to_string(),
                    args: vec![
                        IrExpr::Str("echo".to_string(), StrStyle::DoubleQuoted),
                        IrExpr::Array(vec![IrExpr::Call {
                            func: "add".to_string(),
                            args: vec![IrExpr::Int(3), IrExpr::Int(4)],
                        }]),
                    ],
                }),
            ],
            subs: vec![],
            var_types: vec![
                ("a".to_string(), IrType::Int),
                ("b".to_string(), IrType::Int),
            ],
            stmt_lines: vec![],
            var_lengths: vec![],
            var_const: vec![],
            var_lifetimes: vec![],
            var_nospace: vec![],
            var_storage: vec![],
            var_bash_env: vec![],
        };
        let native = analyze_native_num_fns(&prog);
        assert!(native.contains("add"), "add not native-numeric: {native:?}");
        let out = shir_to_c(&prog);
        assert!(
            out.contains("static char *add(long long _p1, long long _p2)"),
            "native signature missing:\n{out}"
        );
    }

